<?php
namespace Tests\Feature;
use App\Services\Marketing\{MarketingEconomyVideoPolicy,MarketingVideoRoutes,MarketingStoryboardContract,MarketingStoryboardOpenAi};
use Illuminate\Support\Facades\Http;
use Tests\TestCase;
class MarketingEconomyVideoModelsTest extends TestCase {
 protected function setUp():void {parent::setUp();Http::preventStrayRequests();}
 private function scene(array $patch=[]):array {return array_replace_recursive(['scene_id'=>'scene','seconds'=>6,'message'=>'货柜','visual'=>'人物介绍货柜','voiceover'=>'介绍货柜','subtitle'=>'货柜','presenter_required'=>true,'director'=>['subject'=>'人物和货柜'],'material_plan'=>['mode'=>'first_last_frames','roles'=>['start_frame','end_frame'],'reason'=>'结束姿态明确'],'frames'=>['start_frame'=>['required'=>true,'person_presence'=>'visible'],'end_frame'=>['required'=>true,'person_presence'=>'visible']]],$patch);}
 private function broll():array {$s=$this->scene(['voiceover'=>'','presenter_required'=>false]);$s['material_plan']=['mode'=>'single_image','roles'=>['start_frame'],'reason'=>'AI安排商品空镜','shot_kind'=>'product_broll','preferred_model'=>'doubao-seedance-1.0-pro-fast'];$s['frames']['start_frame']['person_presence']='absent';return $s;}
 public function test_ordinary_presenter_uses_15_with_frozen_frame_roles_and_audio_price():void {$p=app(MarketingEconomyVideoPolicy::class)->recommend($this->scene());$this->assertSame('seedance-1.5-pro',$p['model']);$this->assertSame(['start_frame','end_frame'],$p['image_roles']);$this->assertSame(318000,$p['public_estimate_microusd']);$this->assertEqualsWithDelta(21.3408,$p['estimated_credits'],0.000001);$this->assertFalse($p['generation_authorized']);Http::assertNothingSent();}
 public function test_only_explicit_safe_product_broll_can_choose_fast():void {$svc=app(MarketingEconomyVideoPolicy::class);$s=$this->broll();$this->assertSame('doubao-seedance-1.0-pro-fast',$svc->recommend($s)['model']);foreach(['speech','person','tail'] as $bad){$c=$s;if($bad==='speech')$c['voiceover']='保留口播';if($bad==='person')$c['frames']['start_frame']['person_presence']='visible';if($bad==='tail')$c['material_plan']=['mode'=>'first_last_frames','roles'=>['start_frame','end_frame'],'reason'=>'保留尾帧','preferred_model'=>'doubao-seedance-1.0-pro-fast'];$this->assertSame('seedance-1.5-pro',$svc->recommend($c)['model']);}Http::assertNothingSent();}
 public function test_unsupported_duration_and_extra_frames_do_not_upgrade_silently():void {$svc=app(MarketingEconomyVideoPolicy::class);$s=$this->scene(['seconds'=>13]);$this->assertSame('needs_review',$svc->recommend($s)['status']);$s=$this->scene();$s['material_plan']=['mode'=>'reference_images','roles'=>['start_frame','end_frame','extra_image'],'reason'=>'三图必要'];$this->assertSame('needs_review',$svc->recommend($s)['status']);Http::assertNothingSent();}
 public function test_payload_whitelist_keeps_ratio_and_speech_never_lands_on_fast():void {$svc=app(MarketingVideoRoutes::class);$catalog=$svc->catalog();$this->assertArrayHasKey('seedance-1.5-pro',$catalog);$base=['model'=>'seedance-1.5-pro','duration'=>6,'quality'=>'720p','aspect_ratio'=>'9:16','generate_audio'=>true,'content_filter'=>true,'prompt'=>'介绍货柜'];$route=['video'=>['model'=>$base['model']],'capability'=>$catalog[$base['model']]];$out=$svc->payload($base,$route);$this->assertArrayNotHasKey('content_filter',$out);$this->assertTrue($out['generate_audio']);$this->assertSame('9:16',$out['aspect_ratio']);$base['model']='doubao-seedance-1.0-pro-fast';$route=['video'=>['model'=>$base['model']],'capability'=>$catalog[$base['model']]];$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface::class);$svc->payload($base,$route);}
 public function test_ai_model_choice_survives_contract_and_schema():void {$s=$this->broll();$out=app(MarketingStoryboardContract::class)->content($s);$this->assertSame('doubao-seedance-1.0-pro-fast',$out['material_plan']['preferred_model']);$schema=app(MarketingStoryboardOpenAi::class)->schema();$this->assertArrayHasKey('preferred_model',$schema['properties']['scenes']['items']['properties']['material_plan']['properties']);Http::assertNothingSent();}
 public function test_native_audio_switch_and_explicit_voice_have_different_costs():void {$svc=app(MarketingEconomyVideoPolicy::class);$s=$this->scene();$r=$svc->recommend($s,['voice'=>['mode'=>'preset','id'=>'keep-this-voice']]);$this->assertSame('independent_voice_unpriced',$r['audio_route']);$this->assertSame(162000,$r['public_estimate_microusd']);$this->assertSame(1,$r['voice_requests']);$r=$svc->recommend($s,['voice'=>['mode'=>'none']]);$this->assertSame('silent',$r['audio_route']);$this->assertSame(162000,$r['public_estimate_microusd']);$b=$this->broll();$b['seconds']=3;$this->assertSame('doubao-seedance-1.0-pro-fast',$svc->recommend($b)['model']);Http::assertNothingSent();}
 public function test_ai_intent_cannot_set_execution_price_or_permissions():void {$s=$this->broll();$s['material_plan']['cap_microusd']=1;$this->expectException(\Illuminate\Validation\ValidationException::class);app(MarketingStoryboardContract::class)->content($s);}
 public function test_unbounded_economy_prompt_is_rejected_before_transport_without_truncating():void {$svc=app(MarketingVideoRoutes::class);$route=['video'=>['model'=>'seedance-1.5-pro'],'capability'=>$svc->catalog()['seedance-1.5-pro']];$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface::class);$svc->payload(['model'=>'seedance-1.5-pro','duration'=>6,'quality'=>'720p','generate_audio'=>true,'prompt'=>str_repeat('x',2001)],$route);}
}
